import pandas as pd, numpy as np
from sklearn.compose import ColumnTransformer
from sklearn.preprocessing import OneHotEncoder
from sklearn.pipeline import Pipeline
from sklearn.ensemble import GradientBoostingClassifier, HistGradientBoostingClassifier, RandomForestClassifier, VotingClassifier
from sklearn.model_selection import train_test_split
from sklearn.metrics import accuracy_score

df = pd.read_csv("/app/data/train_data.csv", sep="|")
for c in df.select_dtypes(include=["object"]).columns:
    df[c] = df[c].str.strip()
target = df.columns[-1]
X = df.drop(columns=[target])
y = (df[target] == ">50K").astype(int)
cat_cols = X.select_dtypes(include=["object"]).columns.tolist()
num_cols = [c for c in X.columns if c not in cat_cols]
pre_dense = ColumnTransformer([("cat", OneHotEncoder(handle_unknown="ignore", sparse_output=False), cat_cols), ("num", "passthrough", num_cols)])

def build(name):
    if name == "gbm_d4_600":
        return GradientBoostingClassifier(n_estimators=600, learning_rate=0.05, max_depth=4, subsample=0.9, random_state=42)
    if name == "gbm_d4_400":
        return GradientBoostingClassifier(n_estimators=400, learning_rate=0.08, max_depth=4, subsample=0.9, random_state=42)
    if name == "gbm_d5_300":
        return GradientBoostingClassifier(n_estimators=300, learning_rate=0.08, max_depth=5, subsample=0.9, random_state=42)
    if name == "hgb":
        return HistGradientBoostingClassifier(max_iter=500, learning_rate=0.08, max_leaf_nodes=31, random_state=42)
    if name == "vote":
        return VotingClassifier(estimators=[
            ("gbm", GradientBoostingClassifier(n_estimators=400, learning_rate=0.08, max_depth=4, subsample=0.9, random_state=42)),
            ("hgb", HistGradientBoostingClassifier(max_iter=500, learning_rate=0.08, max_leaf_nodes=31, random_state=42)),
            ("rf", RandomForestClassifier(n_estimators=200, max_depth=20, min_samples_leaf=2, n_jobs=-1, random_state=42)),
        ], voting="soft")

names = ["gbm_d4_600", "gbm_d4_400", "gbm_d5_300", "hgb", "vote"]
for seed in [42, 7]:
    Xtr, Xva, ytr, yva = train_test_split(X, y, test_size=0.2, random_state=seed, stratify=y)
    for name in names:
        p = Pipeline([("pre", pre_dense), ("clf", build(name))])
        p.fit(Xtr, ytr)
        acc = accuracy_score(yva, p.predict(Xva))
        print(f"seed{seed} {name} {acc:.4f}", flush=True)
